-- Ringkasan navigasi CP; bukan rumusan resmi lengkap. Jalankan setelah 026.
BEGIN;
ON CONFLICT (reference_code) DO UPDATE SET cp_excerpt=EXCLUDED.cp_excerpt,source_title=EXCLUDED.source_title,source_url=EXCLUDED.source_url,source_version=EXCLUDED.source_version,updated_at=now();
SELECT 'KKA','Koding dan Kecerdasan Artifisial','Pilihan sesuai kesiapan sekolah, Fase C.',ARRAY['C']::public.class_phase[]
WHERE NOT EXISTS (SELECT 1 FROM public.subjects WHERE upper(btrim(code))='KKA' OR lower(btrim(name))='koding dan kecerdasan artifisial');
COMMIT;
NOTIFY pgrst, 'reload schema';
SELECT subject_name,phase,count(*) FROM public.curriculum_cp_catalog WHERE active GROUP BY subject_name,phase ORDER BY subject_name,phase;
